-- sqlite DDL for `employees`, generated by megasamples from the MySQL corpus. Do not edit:
-- the next port rewrites it. Data is loaded from the MySQL Shell dump, not from here.

CREATE TABLE "departments" (
  "dept_no" CHAR(4) NOT NULL,
  "dept_name" VARCHAR(40) NOT NULL,
  PRIMARY KEY ("dept_no")
);

CREATE TABLE "employees" (
  "emp_no" INTEGER NOT NULL,
  "birth_date" DATE NOT NULL,
  "first_name" VARCHAR(14) NOT NULL,
  "last_name" VARCHAR(16) NOT NULL,
  "gender" TEXT NOT NULL CHECK ("gender" IN ('M', 'F')),
  "hire_date" DATE NOT NULL,
  PRIMARY KEY ("emp_no")
);

CREATE TABLE "dept_emp" (
  "emp_no" INTEGER NOT NULL,
  "dept_no" CHAR(4) NOT NULL,
  "from_date" DATE NOT NULL,
  "to_date" DATE NOT NULL,
  PRIMARY KEY ("emp_no", "dept_no"),
  CONSTRAINT "dept_emp_ibfk_1" FOREIGN KEY ("emp_no") REFERENCES "employees" ("emp_no") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "dept_emp_ibfk_2" FOREIGN KEY ("dept_no") REFERENCES "departments" ("dept_no") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "dept_manager" (
  "emp_no" INTEGER NOT NULL,
  "dept_no" CHAR(4) NOT NULL,
  "from_date" DATE NOT NULL,
  "to_date" DATE NOT NULL,
  PRIMARY KEY ("emp_no", "dept_no"),
  CONSTRAINT "dept_manager_ibfk_1" FOREIGN KEY ("emp_no") REFERENCES "employees" ("emp_no") ON UPDATE NO ACTION ON DELETE CASCADE,
  CONSTRAINT "dept_manager_ibfk_2" FOREIGN KEY ("dept_no") REFERENCES "departments" ("dept_no") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "salaries" (
  "emp_no" INTEGER NOT NULL,
  "salary" INTEGER NOT NULL,
  "from_date" DATE NOT NULL,
  "to_date" DATE NOT NULL,
  PRIMARY KEY ("emp_no", "from_date"),
  CONSTRAINT "salaries_ibfk_1" FOREIGN KEY ("emp_no") REFERENCES "employees" ("emp_no") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "titles" (
  "emp_no" INTEGER NOT NULL,
  "title" VARCHAR(50) NOT NULL,
  "from_date" DATE NOT NULL,
  "to_date" DATE,
  PRIMARY KEY ("emp_no", "title", "from_date"),
  CONSTRAINT "titles_ibfk_1" FOREIGN KEY ("emp_no") REFERENCES "employees" ("emp_no") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE UNIQUE INDEX "departments_dept_name" ON "departments" ("dept_name");
CREATE INDEX "dept_emp_dept_no" ON "dept_emp" ("dept_no");
CREATE INDEX "dept_manager_dept_no" ON "dept_manager" ("dept_no");

CREATE VIEW "dept_emp_latest_date" ("emp_no", "from_date", "to_date") AS
SELECT "dept_emp"."emp_no" AS "emp_no", MAX("dept_emp"."from_date") AS "from_date", MAX("dept_emp"."to_date") AS "to_date" FROM "dept_emp" GROUP BY "dept_emp"."emp_no";

CREATE VIEW "current_dept_emp" ("emp_no", "dept_no", "from_date", "to_date") AS
SELECT "l"."emp_no" AS "emp_no", "d"."dept_no" AS "dept_no", "l"."from_date" AS "from_date", "l"."to_date" AS "to_date" FROM ("dept_emp" AS "d" JOIN "dept_emp_latest_date" AS "l" ON ((("d"."emp_no" = "l"."emp_no") AND ("d"."from_date" = "l"."from_date") AND ("l"."to_date" = "d"."to_date"))));
